rendering.css:
html {
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
  font-feature-settings: 'kern' 1;
  font-kerning: normal;
}

::selection {
  background: var(--color-accent);
  color: var(--color-bg);
}

editorial_precision.css_vars:
--font-display: 'Instrument Serif', Georgia, serif;
--font-body: 'Space Grotesk', system-ui, sans-serif;
--font-mono: 'Space Mono', monospace;
--ls-display: -0.03em;
--ls-body: -0.01em;
--ls-caption: 0.1em;
--lh-display: 1.0;
--lh-body: 1.6;

raw_elegance.css_vars:
--font-display: 'Newsreader', 'Times New Roman', serif;
--font-body: 'DM Sans', system-ui, sans-serif;
--ls-display: -0.04em;
--ls-body: 0;
--ls-caption: 0.12em;
--lh-display: 0.95;
--lh-body: 1.65;

spacing_system.css:
:root {
  --section-pad: clamp(6rem, 12vh, 10rem);
  --gap-l: clamp(4rem, 8vh, 7rem);
  --gap-m: clamp(2rem, 4vh, 3.5rem);
  --gap-s: clamp(1rem, 2vh, 1.5rem);
  --max-w: 1400px;
  --max-w-narrow: 900px;
  --max-w-wide: 1600px;
  --pad-x: clamp(1.5rem, 5vw, 4rem);
  --grid-gap: clamp(1rem, 2vw, 2rem);
}
